package com.coffeeshop.repository;import com.coffeeshop.dto.ExpenseCommands;import com.coffeeshop.exception.DatabaseException;import com.coffeeshop.model.ExpenseModels;import javax.sql.DataSource;import java.sql.*;import java.util.*;public final class JdbcExpenseRepository implements ExpenseRepository{private final DataSource ds;public JdbcExpenseRepository(DataSource d){ds=Objects.requireNonNull(d);}public ExpenseModels.Catalog load(){try(Connection c=ds.getConnection()){return new ExpenseModels.Catalog(categories(c),expenses(c));}catch(SQLException e){throw fail("Unable to load expenses.",e);}}private List<ExpenseModels.Category>categories(Connection c)throws SQLException{try(PreparedStatement s=c.prepareStatement("SELECT expense_category_id,category_code,category_name,is_active,row_version FROM dbo.expense_categories ORDER BY category_name");ResultSet r=s.executeQuery()){List<ExpenseModels.Category>x=new ArrayList<>();while(r.next())x.add(new ExpenseModels.Category(r.getLong(1),r.getString(2),r.getString(3),r.getBoolean(4),r.getBytes(5)));return x;}}private List<ExpenseModels.Expense>expenses(Connection c)throws SQLException{String q="SELECT e.expense_id,e.expense_number,e.expense_category_id,c.category_name,e.expensed_at,e.amount,e.description,e.reference_number,e.notes,u.username,e.row_version FROM dbo.expenses e JOIN dbo.expense_categories c ON c.expense_category_id=e.expense_category_id JOIN dbo.users u ON u.user_id=e.recorded_by_user_id ORDER BY e.expensed_at DESC,e.expense_id DESC";try(PreparedStatement s=c.prepareStatement(q);ResultSet r=s.executeQuery()){List<ExpenseModels.Expense>x=new ArrayList<>();while(r.next())x.add(new ExpenseModels.Expense(r.getLong(1),r.getString(2),r.getLong(3),r.getString(4),r.getTimestamp(5).toLocalDateTime(),r.getBigDecimal(6),r.getString(7),r.getString(8),r.getString(9),r.getString(10),r.getBytes(11)));return x;}}public long saveCategory(ExpenseCommands.Category q){String sql=q.id()==null?"INSERT dbo.expense_categories(category_code,category_name,is_active) VALUES(?,?,?)":"UPDATE dbo.expense_categories SET category_code=?,category_name=?,is_active=?,updated_at=SYSUTCDATETIME() WHERE expense_category_id=? AND row_version=?";try(Connection c=ds.getConnection();PreparedStatement s=c.prepareStatement(sql,Statement.RETURN_GENERATED_KEYS)){s.setString(1,q.code());s.setString(2,q.name());s.setBoolean(3,q.active());if(q.id()!=null){s.setLong(4,q.id());s.setBytes(5,q.version());one(s.executeUpdate());return q.id();}s.executeUpdate();return key(s);}catch(SQLException e){throw fail("Unable to save expense category. Check code and name uniqueness.",e);}}public void setCategoryActive(long id,boolean active,byte[]v){try(Connection c=ds.getConnection();PreparedStatement s=c.prepareStatement("UPDATE dbo.expense_categories SET is_active=?,updated_at=SYSUTCDATETIME() WHERE expense_category_id=? AND row_version=?")){s.setBoolean(1,active);s.setLong(2,id);s.setBytes(3,v);one(s.executeUpdate());}catch(SQLException e){throw fail("Unable to update expense category.",e);}}public long saveExpense(ExpenseCommands.Expense q,long user){try(Connection c=ds.getConnection()){c.setAutoCommit(false);try{long id;if(q.id()==null){String sql="INSERT dbo.expenses(expense_category_id,expense_number,expensed_at,amount,description,reference_number,notes,recorded_by_user_id) VALUES(?,CONCAT((SELECT COALESCE(MAX(CASE WHEN setting_key='numbering.expense.prefix' THEN setting_value END),'EXP') FROM dbo.settings),FORMAT(NEXT VALUE FOR dbo.seq_expense_number,'00000000')),?,?,?,?,?,?)";try(PreparedStatement s=c.prepareStatement(sql,Statement.RETURN_GENERATED_KEYS)){params(s,q);s.setLong(7,user);s.executeUpdate();id=key(s);}}else{id=q.id();try(PreparedStatement s=c.prepareStatement("UPDATE dbo.expenses SET expense_category_id=?,expensed_at=?,amount=?,description=?,reference_number=?,notes=?,updated_at=SYSUTCDATETIME() WHERE expense_id=? AND row_version=?")){params(s,q);s.setLong(7,id);s.setBytes(8,q.version());one(s.executeUpdate());}}c.commit();return id;}catch(Exception e){c.rollback();throw e;}}catch(RuntimeException e){throw e;}catch(Exception e){throw fail("Unable to save expense.",e);}}private static void params(PreparedStatement s,ExpenseCommands.Expense q)throws SQLException{s.setLong(1,q.categoryId());s.setTimestamp(2,Timestamp.valueOf(q.expensedAt()));s.setBigDecimal(3,q.amount());nullable(s,4,q.description());nullable(s,5,q.reference());nullable(s,6,q.notes());}private static void nullable(PreparedStatement s,int i,String v)throws SQLException{if(v==null)s.setNull(i,Types.NVARCHAR);else s.setString(i,v);}private static void one(int n){if(n!=1)throw new IllegalStateException("Record changed. Refresh and try again.");}private static long key(PreparedStatement s)throws SQLException{try(ResultSet r=s.getGeneratedKeys()){if(!r.next())throw new SQLException("Generated key unavailable");return r.getLong(1);}}private static DatabaseException fail(String m,Exception e){return new DatabaseException(m,e);}}
